style.css:
@-moz-document domain("roblox.com") {
/* 1. FOND D'ÉCRAN GENERAL SONIC */
    body, 
    .dark-theme, 
    #container-main, 
    .content, 
    .main-layout, 
    .gui-neutral-bg {
        background: url("https://images.alphacoders.com/134/1341052.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. TRANSPARENCE DES BLOCS */
    .section-content, 
    .game-card-container, 
    .dynamic-game-grid,
    .left-col-navigation-v2, 
    .rbx-left-col {
        background: rgba(16, 24, 48, 0.75) !important;
        border-radius: 12px !important;
        padding: 10px !important;
    }

    /* 3. BARRE DU HAUT BLEU SONIC */
    .rbx-header {
        background-color: #0054a6 !important;
        box-shadow: 0px 4px 15px rgba(0, 84, 166, 0.6) !important;
    }

    /* 4. BOUTONS BLEUS */
    .btn-secondary-xs, .see-all-link, .btn-primary-md {
        background-color: #0066cc !important;
        border-color: #0088ff !important;
        color: #ffffff !important;
        border-radius: 6px !important;
    }
    .btn-secondary-xs:hover, .see-all-link:hover {
        background-color: #0088ff !important;
    }

    /* 5. TEXTES ET LIENS */
    .text-link, a {
        color: #00bfff !important;
    }

    /* 6. LE COMPTEUR DE ROBUX - TECHNIQUE DU PSEUDO-ELEMENT */
    /* On force l'icône blanche de base à devenir invisible */
    span#nav-robux.icon-robux-28x28 {
        background: transparent !important;
        position: relative !important;
        width: 28px !important;
        height: 28px !important;
        display: inline-block !important;
    }

    /* On crée le nouveau Sonic juste au-dessus */
    span#nav-robux.icon-robux-28x28::before {
        content: "" !important;
        position: absolute !important;
        left: 0 !important;
        top: 0 !important;
        width: 100% !important;
        height: 100% !important;
        background-image: url("https://i.ibb.co/vxs4gYmJ/sonic-money.png") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
    }
}
